parameters.jsCode:
// Validate AI output
const output = $input.first().json.output || $input.first().json.text || '';
let parsed;
try {
  // Try direct parse
  parsed = JSON.parse(output);
} catch {
  // Try extracting from markdown
  const match = output.match(/```(?:json)?\s*\n?([\s\S]*?)\n?```/) || output.match(/\{[\s\S]*\}/);
  if (match) {
    try { parsed = JSON.parse(match[1] || match[0]); } catch { parsed = null; }
  }
}

if (!parsed) {
  return [{ json: { valid: false, error: 'Failed to parse AI output', raw: output.substring(0, 500) } }];
}

const VALID_URGENCY = ['EMERGENCY', 'URGENT', 'ROUTINE', 'NON_URGENT'];
const errors = [];
if (!VALID_URGENCY.includes(parsed.urgency)) errors.push('Invalid urgency');
if (typeof parsed.risk_score !== 'number' || parsed.risk_score < 0 || parsed.risk_score > 10) errors.push('Invalid risk_score');
if (!parsed.specialty) errors.push('Missing specialty');
if (!parsed.summary) errors.push('Missing summary');

if (errors.length > 0) {
  return [{ json: { valid: false, errors, parsed } }];
}

return [{ json: { valid: true, triage: parsed } }];
